-- =============================================================
-- Smart Carpool and Ride-Sharing System - MySQL Database Setup
-- =============================================================

CREATE DATABASE IF NOT EXISTS `ridesharing_db` 
CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE `ridesharing_db`;

-- Note: Spring Boot Data JPA automatically manages table creation and updates 
-- via hibernate.ddl-auto=update.
-- The tables below show the relational schema generated by the entities.

-- 1. Roles table
CREATE TABLE IF NOT EXISTS `roles` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(50) NOT NULL UNIQUE
) ENGINE=InnoDB;

-- 2. Users table
CREATE TABLE IF NOT EXISTS `users` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `email` VARCHAR(100) NOT NULL UNIQUE,
    `password` VARCHAR(255) NOT NULL,
    `full_name` VARCHAR(100) NOT NULL,
    `phone` VARCHAR(20),
    `active` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_user_email (`email`)
) ENGINE=InnoDB;

-- 3. User Roles mapping table
CREATE TABLE IF NOT EXISTS `user_roles` (
    `user_id` BIGINT NOT NULL,
    `role_id` BIGINT NOT NULL,
    PRIMARY KEY (`user_id`, `role_id`),
    CONSTRAINT fk_user_roles_user FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT fk_user_roles_role FOREIGN KEY (`role_id`) REFERENCES `roles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

-- 4. Vehicles table
CREATE TABLE IF NOT EXISTS `vehicles` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `driver_id` BIGINT NOT NULL,
    `make` VARCHAR(50) NOT NULL,
    `model` VARCHAR(50) NOT NULL,
    `model_year` INT NOT NULL,
    `license_plate` VARCHAR(30) NOT NULL UNIQUE,
    `color` VARCHAR(30),
    `capacity` INT NOT NULL,
    `active` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_vehicle_driver FOREIGN KEY (`driver_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

-- 5. Rides table
CREATE TABLE IF NOT EXISTS `rides` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `driver_id` BIGINT NOT NULL,
    `vehicle_id` BIGINT NOT NULL,
    `source_address` VARCHAR(255) NOT NULL,
    `source_latitude` DOUBLE NOT NULL,
    `source_longitude` DOUBLE NOT NULL,
    `destination_address` VARCHAR(255) NOT NULL,
    `destination_latitude` DOUBLE NOT NULL,
    `destination_longitude` DOUBLE NOT NULL,
    `departure_date` DATE NOT NULL,
    `departure_time` TIME NOT NULL,
    `total_seats` INT NOT NULL,
    `available_seats` INT NOT NULL,
    `total_trip_cost` DECIMAL(10,2) NOT NULL,
    `driver_contribution_percent` DOUBLE NOT NULL DEFAULT 0.0,
    `passenger_cost` DECIMAL(10,2) NOT NULL,
    `notes` TEXT,
    `status` VARCHAR(20) NOT NULL DEFAULT 'PLANNED',
    `version` BIGINT NOT NULL DEFAULT 0,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_ride_date (`departure_date`),
    INDEX idx_ride_status (`status`),
    CONSTRAINT fk_ride_driver FOREIGN KEY (`driver_id`) REFERENCES `users` (`id`),
    CONSTRAINT fk_ride_vehicle FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`)
) ENGINE=InnoDB;

-- 6. Intermediate Ride Stops
CREATE TABLE IF NOT EXISTS `ride_stops` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `ride_id` BIGINT NOT NULL,
    `stop_name` VARCHAR(255) NOT NULL,
    `latitude` DOUBLE NOT NULL,
    `longitude` DOUBLE NOT NULL,
    `stop_order` INT NOT NULL,
    CONSTRAINT fk_stop_ride FOREIGN KEY (`ride_id`) REFERENCES `rides` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

-- 7. Bookings table
CREATE TABLE IF NOT EXISTS `bookings` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `ride_id` BIGINT NOT NULL,
    `passenger_id` BIGINT NOT NULL,
    `seats_booked` INT NOT NULL,
    `total_fare` DECIMAL(10,2) NOT NULL,
    `pickup_location` VARCHAR(255),
    `dropoff_location` VARCHAR(255),
    `status` VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    `booking_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `cancellation_reason` VARCHAR(255),
    `rated` BOOLEAN NOT NULL DEFAULT FALSE,
    `version` BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT fk_booking_ride FOREIGN KEY (`ride_id`) REFERENCES `rides` (`id`),
    CONSTRAINT fk_booking_passenger FOREIGN KEY (`passenger_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB;

-- 8. Ratings and Reviews table
CREATE TABLE IF NOT EXISTS `ratings` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `booking_id` BIGINT NOT NULL UNIQUE,
    `ride_id` BIGINT NOT NULL,
    `passenger_id` BIGINT NOT NULL,
    `driver_id` BIGINT NOT NULL,
    `score` INT NOT NULL,
    `comment` TEXT,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_rating_booking FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`),
    CONSTRAINT fk_rating_ride FOREIGN KEY (`ride_id`) REFERENCES `rides` (`id`),
    CONSTRAINT fk_rating_passenger FOREIGN KEY (`passenger_id`) REFERENCES `users` (`id`),
    CONSTRAINT fk_rating_driver FOREIGN KEY (`driver_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB;

-- 9. Notifications table
CREATE TABLE IF NOT EXISTS `notifications` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `recipient_id` BIGINT NOT NULL,
    `title` VARCHAR(150) NOT NULL,
    `message` TEXT NOT NULL,
    `type` VARCHAR(40) NOT NULL,
    `is_read` BOOLEAN NOT NULL DEFAULT FALSE,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    INDEX idx_notif_recipient (`recipient_id`),
    CONSTRAINT fk_notification_recipient FOREIGN KEY (`recipient_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB;

-- 10. Reports table
CREATE TABLE IF NOT EXISTS `reports` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `reporter_id` BIGINT NOT NULL,
    `reported_user_id` BIGINT,
    `reported_ride_id` BIGINT,
    `reason` TEXT NOT NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    `admin_notes` TEXT,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_report_reporter FOREIGN KEY (`reporter_id`) REFERENCES `users` (`id`),
    CONSTRAINT fk_report_user FOREIGN KEY (`reported_user_id`) REFERENCES `users` (`id`),
    CONSTRAINT fk_report_ride FOREIGN KEY (`reported_ride_id`) REFERENCES `rides` (`id`)
) ENGINE=InnoDB;
